{
  "findings": [
    {
      "check_id": "CKV2_AWS_41",
      "title": "EC2 instance has no IAM role attached",
      "resource": "aws_instance.web",
      "severity": "MEDIUM",
      "explanation": "The EC2 instance has no IAM instance profile, preventing workloads from using scoped, temporary AWS credentials through an attached role."
    },
    {
      "check_id": "CKV_AWS_88",
      "title": "EC2 instance may receive a public IP",
      "resource": "aws_instance.web",
      "severity": "MEDIUM",
      "explanation": "The instance is placed in a public subnet without explicitly disabling public IP assignment, which may expose it directly to the internet."
    },
    {
      "check_id": "AVD-AWS-0028",
      "title": "IMDSv2 is not required",
      "resource": "aws_instance.web",
      "severity": "HIGH",
      "explanation": "The instance does not require metadata service tokens, allowing use of IMDSv1 and increasing the risk of credential theft through server-side request forgery."
    }
  ],
  "patched_code": "resource "aws_iam_role" "web" {
  name_prefix = "web-instance-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_instance_profile" "web" {
  name_prefix = "web-instance-"
  role        = aws_iam_role.web.name
}

resource "aws_instance" "web" {
  ami                         = "${var.ami}"
  instance_type               = "t2.micro"
  subnet_id                   = "${aws_subnet.public-subnet.id}"
  vpc_security_group_ids      = ["${aws_security_group.sgweb.id}"]
  iam_instance_profile        = aws_iam_instance_profile.web.name
  associate_public_ip_address = false

  metadata_options {
    http_tokens = "required"
  }
}
",
  "fix_summary": "Attached a least-privilege EC2 IAM role through an instance profile, explicitly disabled public IP assignment, and required IMDSv2 tokens."
}
